The copy prevents callers from accidentally changing the cached response. Failed requests aren’t cached. The cache is local to each process and has no time-based expiration; call `_fetch_user_cached.cache_clear()` to invalidate all entries when needed.

```python
from functools import lru_cache

import requests


@lru_cache(maxsize=128)
def fetch_user(user_id: int) -> dict:
    response = requests.get(f"https://api.example.com/users/{user_id}")
    response.raise_for_status()
    return response.json()
```

This caches up to 128 successful responses per process, with no time-based expiration. Call `fetch_user.cache_clear()` to invalidate them, and treat returned dictionaries as read-only: cache hits return the same object.

Make `load()` async, use `URLSession` for the download, and move synchronous parsing into an `@concurrent` helper. The model stays on the main actor; the helper explicitly runs off it.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: String?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let parsed = try await Self.fetchItems(from: feedURL)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession cancellation can surface as a URLError.
            guard !Task.isCancelled else { return }
            loadError = error.localizedDescription
        }
    }

    @concurrent
    nonisolated private static func fetchItems(from url: URL) async throws -> [Item] {
        let (data, response) = try await URLSession.shared.data(from: url)

        guard let http = response as? HTTPURLResponse,
              (200..<300).contains(http.statusCode) else {
            throw URLError(.badServerResponse)
        }

        try Task.checkCancellation()
        return Parser.parse(data)
    }
}
```

In a main-actor-by-default target, make sure `Parser.parse` and the code it calls are nonisolated. If `Parser` is a stateless utility, you can mark the whole declaration `nonisolated enum Parser`. Since `[Item]` crosses back to the main actor, `Item` must be `Sendable`; a `nonisolated struct Item: Sendable` with sendable fields is a natural fit.

In SwiftUI, call it with `.task { await model.load() }` so the view owns cancellation. A plain `Task { ... }` created on the main actor would inherit that isolation and would not, by itself, move synchronous parsing off the main actor.

Use `URLSession` for the fetch, keep UI state on the main actor, and use `@concurrent` to run synchronous parsing off the main actor. In Swift 6.2, `async` alone doesn’t guarantee that CPU-bound work leaves the caller’s actor.

```swift
import Combine
import Foundation

@MainActor
final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            try Task.checkCancellation()
            let parsed = await Self.parseOffMain(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession can report cancellation as a URLError.
            if !Task.isCancelled {
                loadError = error
            }
        }
    }

    @concurrent
    private static func parseOffMain(_ data: Data) async -> [Item] {
        Parser.parse(data)
    }
}
```

If `Parser` is declared in the same main-actor-by-default target, mark the parser type (or its stateless `parse` method and any helpers it calls) `nonisolated`. Make `Item` a `Sendable` value type, with nonisolated construction and decoding where needed, so `[Item]` can safely cross back to the main actor. Don’t opt a parser out of actor isolation if it relies on shared mutable state.

In SwiftUI, call this with `.task { await model.load() }` so the view owns cancellation. The cancellation checks prevent publishing stale results; they don’t interrupt a synchronous parse already in progress. If `Parser.parse` can fail, make the helper `async throws` and call it with `try await` so parse failures also reach `loadError`.

Keep the model on the main actor, use `URLSession` for asynchronous I/O, and put synchronous parsing in an `@concurrent` function so it runs off the main actor. Make `load()` async so the caller can own its lifetime.

```swift
