import Foundation
import Observation

@Observable
final class FeedModel {
    private(set) var items: [Item] = []
    private(set) var isLoading = false
    private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading, !Task.isCancelled else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode) else {
                throw URLError(.badServerResponse)
            }

            let parsed = try await Self.parse(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            if !Task.isCancelled {
                loadError = error
            }
        }
    }

    @concurrent
    private static func parse(_ data: Data) async throws -> [Item] {
        try Task.checkCancellation()
        return Parser.parse(data)
    }
}
```

- **Isolation:** With Default Actor Isolation set to `MainActor`, the model doesn’t need an explicit annotation. `URLSession` suspends without blocking the UI. In Swift 6.2, `async` alone doesn’t move synchronous parsing off the caller’s actor; `@concurrent` does.
- **Parser and items:** Make `Parser.parse` callable off-main—for example, declare a stateless parser namespace as `nonisolated enum Parser`. Make `Item` a `Sendable` value type with sendable fields and nonisolated construction, since `[Item]` crosses back to the main actor. If parsing is cheap, call `Parser.parse` directly from `load()` and omit the concurrent helper.
- **Task lifetime:** In SwiftUI, use `.task { await model.load() }` so SwiftUI cancels the task when the view disappears. The `isLoading` guard ignores overlapping calls, and the cancellation check after parsing prevents a canceled load from publishing its results. It doesn’t interrupt a synchronous parser already in progress.

If you still have Combine consumers of `$items` or `$isLoading`, keep `ObservableObject` and `@Published` instead of switching to `@Observable`; the concurrency changes are the same.

Use `URLSession` for the network request and keep the observable state on the main actor. `await` lets the request suspend without blocking the UI; it does **not** move synchronous parsing off the main actor. If profiling shows parsing is expensive—or you want to preserve the original off-main behavior—give parsing an explicit `@concurrent` boundary.

```swift
import Foundation
import Observation

@Observable
final class FeedModel {
    private(set) var items: [Item] = []
    private(set) var isLoading = false
    private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading, !Task.isCancelled else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            guard let response = response as? HTTPURLResponse,
                  (200..<300).contains(response.statusCode) else {
                throw URLError(.badServerResponse)
            }

            let parsed = try await parseFeed(data)
            try Task.checkCancellation()
            items = parsed
        } catch is CancellationError {
            // Cancellation isn't a loading failure.
        } catch {
            // URLSession can also report cancellation as a URLError.
            if !Task.isCancelled {
                loadError = error
            }
        }
    }
}

@concurrent
private func parseFeed(_ data: Data) async throws -> [Item] {
    try Task.checkCancellation()
    return Parser.parse(data)
}
```

- **Parser and item types:** `Parser.parse` must be callable off the main actor. If you own a stateless parser, declare it as a `nonisolated enum Parser`, or mark just `parse` as `nonisolated` if it doesn’t use actor-isolated state. Make `Item` a `Sendable` value type; if its declaration is in this main-actor-by-default target, use `nonisolated struct Item: Sendable` with sendable stored properties.
- **Task lifetime:** In SwiftUI, call it with `.task { await model.load() }` so the view manages cancellation. The `isLoading` guard ignores overlapping calls, and the cancellation check after parsing prevents a cancelled load from publishing items. It doesn’t interrupt a synchronous parser already running.
- **If parsing is cheap:** Replace `try await parseFeed(data)` with `Parser.parse(data)` and delete the helper. You no longer need to make `Parser` or `Item` cross an isolation boundary.

This assumes an HTTP(S) feed and an Observation-supported deployment target. If you still need Combine or older OS support, keep `ObservableObject` and `@Published`; the async loading design is unchanged.

