```swift
import Combine
import Foundation

@MainActor // Implicit in this target; explicit here for clarity.
final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        // Ignore overlapping requests while a load is in progress.
        guard !isLoading, !Task.isCancelled else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            guard let http = response as? HTTPURLResponse,
                  (200..<300).contains(http.statusCode) else {
                throw URLError(.badServerResponse)
            }

            let parsed = try await parseFeed(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession can report cancellation as URLError.cancelled.
            guard !Task.isCancelled else { return }
            loadError = error
        }
    }
}

@concurrent
private func parseFeed(_ data: Data) async throws -> [Item] {
    try Task.checkCancellation()
    return Parser.parse(data)
}
```

This assumes an HTTP(S) feed and a nonthrowing `Parser.parse`, as in the original. In a main-actor-by-default target, make `Parser` explicitly `nonisolated` (or opt out on `parse` and the helpers it uses). Make `Item` a `Sendable` value type so `[Item]` can cross back to the main actor.

In SwiftUI, call it with `.task { await model.load() }` so the view owns cancellation. Cancellation won’t interrupt a synchronous parser mid-call, but the check before assigning `items` prevents a cancelled load from publishing its result. If profiling shows that parsing is cheap, call it directly and omit the `@concurrent` helper.

Make `load()` async so the caller owns its lifetime. Use `URLSession` for the fetch and an `@concurrent` helper for synchronous parsing. The model stays on the main actor under the target’s default isolation.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        // Ignore overlapping requests while a load is in flight.
        guard !isLoading, !Task.isCancelled else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)
            if let http = response as? HTTPURLResponse,
               !(200..<300).contains(http.statusCode) {
                throw URLError(.badServerResponse)
            }

            let parsed = try await parseFeed(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession can report cancellation as URLError.cancelled.
            if !Task.isCancelled {
                loadError = error
            }
        }
    }
}

@concurrent
private func parseFeed(_ data: Data) async throws -> [Item] {
    try Task.checkCancellation()
    return Parser.parse(data)
}
```

If `Item` and `Parser` are declared in the same main-actor-by-default target, make `Item` a `nonisolated` value type conforming to `Sendable`, and opt `Parser` (or its `parse` method) out of main-actor isolation. The parser must not access main-actor state or unsynchronized shared mutable state. If `Parser.parse` itself throws, use `return try Parser.parse(data)`.

In SwiftUI, call it with `.task { await model.load() }` so SwiftUI can cancel it when the view disappears. Cancellation prevents publishing a stale result, but it won’t interrupt a synchronous parser mid-run unless the parser checks for cancellation itself.

Make `load()` async, use `URLSession` for the download, and put `@concurrent` on the parsing step. The model stays on the main actor, so there’s no need to dispatch state updates back to the main queue.

```swift
import Combine
import Foundation

final class FeedModel: ObservableObject {
    @Published private(set) var items: [Item] = []
    @Published private(set) var isLoading = false
    @Published private(set) var loadError: (any Error)?

    private let feedURL: URL

    init(feedURL: URL) {
        self.feedURL = feedURL
    }

    func load() async {
        guard !isLoading, !Task.isCancelled else { return }

        isLoading = true
        loadError = nil
        defer { isLoading = false }

        do {
            let (data, response) = try await URLSession.shared.data(from: feedURL)

            guard let response = response as? HTTPURLResponse,
                  (200..<300).contains(response.statusCode) else {
                throw URLError(.badServerResponse)
            }

            let parsed = try await parseFeed(data)
            try Task.checkCancellation()
            items = parsed
        } catch {
            // URLSession can report cancellation as URLError.cancelled.
            guard !Task.isCancelled else { return }
            loadError = error
        }
    }
}

@concurrent
private func parseFeed(_ data: Data) async throws -> [Item] {
    try Task.checkCancellation()
    return Parser.parse(data)
}
```

In SwiftUI, call it with `.task { await model.load() }` so the view owns the task’s lifetime. The `isLoading` guard makes overlapping calls no-ops, and `defer` resets the flag on success, failure, or cancellation.

**For your existing types:** `Parser.parse` must be callable off the main actor. If `Parser` is defined in the same app target and has no main-actor dependencies, declare it as `nonisolated enum Parser` (or opt out on the method and any helpers it calls). Likewise, make `Item` a `Sendable` value type—for example, `nonisolated struct Item: Sendable` with sendable fields—so `[Item]` can cross back to the main actor. If `Parser.parse` throws, use `return try Parser.parse(data)` so parse failures reach `loadError`.

